/**
 * @brief Gets the text alignment which should be really used. Compared to :ref:`lv_obj_get_style_text_align()` it resolves LV_TEXT_ALIGN_AUTO by considering the base direction of Widget and the text itself. The resolved alignment: LV_TEXT_ALIGN_LEFT/CENTER/RIGHT (never LV_TEXT_ALIGN_AUTO )
 *
 * @param part (number) One of the LV_PART_... enum values
 *
 * @param txt (string) The text to align. Its first strong character determines the direction if the base direction is LV_BASE_DIR_AUTO .
 *
 * @return (number) The resolved alignment: LV_TEXT_ALIGN_LEFT/CENTER/RIGHT (never LV_TEXT_ALIGN_AUTO )
 */
jerry_value_t sni_api_lv_obj_calculate_style_text_align(const jerry_call_info_t *call_info_p,
                                                        const jerry_value_t args_p[],
                                                        const jerry_length_t args_count)
{
    if (args_count != 2)
    {
        return sni_api_throw_error("Invalid argument count");
    }

    if (!jerry_value_is_object(call_info_p->this_value))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    const lv_obj_t *self_obj;
    if (!sni_tb_js2c(call_info_p->this_value, SNI_H_LV_OBJ, &self_obj))
    {
        return sni_api_throw_error("Failed to convert argument");
    }

    if (!jerry_value_is_number(args_p[0]))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    lv_part_t arg_part;
    arg_part = sni_tb_js2c_int32(args_p[0]);

    if (!jerry_value_is_string(args_p[1]))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    const char *arg_txt;
    arg_txt = sni_tb_js2c_string(args_p[1]);
    if (!arg_txt)
    {
        return sni_api_throw_error("Out of memory");
    }

    lv_text_align_t result = lv_obj_calculate_style_text_align(self_obj, arg_part, arg_txt);
    eos_free((void *)arg_txt);
    return sni_tb_c2js(&result, SNI_T_INT32);
}

