/**
 * @brief Create a button object pointer to the created button
 *
 * @param parent (object) pointer to a parent widget May be NULL .. When NULL, the widget is created as a screen on the default display.
 *
 * @return (object) pointer to the created button
 */
jerry_value_t sni_api_ctor_button(const jerry_call_info_t *call_info_p,
                                  const jerry_value_t args_p[],
                                  const jerry_length_t args_count)
{
    if (jerry_value_is_undefined(call_info_p->new_target))
    {
        return sni_api_throw_error("Constructor must be called with new");
    }

    if (args_count != 1)
    {
        return sni_api_throw_error("Invalid argument count");
    }

    lv_obj_t *arg_parent;
    if (!sni_tb_js2c_parent(args_p[0], (void **)&arg_parent))
    {
        return sni_api_throw_error("Parent argument is required");
    }

    lv_obj_t *native_obj = lv_button_create(arg_parent);
    if (!sni_tb_c2js_set_object(&native_obj, SNI_H_LV_OBJ, call_info_p->this_value))
    {
        return sni_api_throw_error("Failed to bind native object");
    }
    return jerry_undefined();
}

/**
 * @brief Create a label object pointer to the created button
 *
 * @param parent (object) pointer to a parent widget May be NULL .. When NULL, the widget is created as a screen on the default display.
 *
 * @return (object) pointer to the created button
 */
jerry_value_t sni_api_ctor_label(const jerry_call_info_t *call_info_p,
                                 const jerry_value_t args_p[],
                                 const jerry_length_t args_count)
{
    if (jerry_value_is_undefined(call_info_p->new_target))
    {
        return sni_api_throw_error("Constructor must be called with new");
    }

    if (args_count != 1)
    {
        return sni_api_throw_error("Invalid argument count");
    }

    lv_obj_t *arg_parent;
    if (!sni_tb_js2c_parent(args_p[0], (void **)&arg_parent))
    {
        return sni_api_throw_error("Parent argument is required");
    }

    lv_obj_t *native_obj = lv_label_create(arg_parent);
    if (!sni_tb_c2js_set_object(&native_obj, SNI_H_LV_OBJ, call_info_p->this_value))
    {
        return sni_api_throw_error("Failed to bind native object");
    }
    return jerry_undefined();
}

/**
 * @brief Set a new text for a label. Memory will be allocated to store the text by the label. If LV_USE_ARABIC_PERSIAN_CHARS is enabled the text will be modified to have the correct Arabic characters in it.
 *
 * @param text (string) '\0' terminated character string. May be NULL . When NULL the label is refreshed with its current text.
 */
jerry_value_t sni_api_lv_label_set_text(const jerry_call_info_t *call_info_p,
                                        const jerry_value_t args_p[],
                                        const jerry_length_t args_count)
{
    if (args_count != 1)
    {
        return sni_api_throw_error("Invalid argument count");
    }

    if (!jerry_value_is_object(call_info_p->this_value))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    lv_obj_t *self_obj;
    if (!sni_tb_js2c(call_info_p->this_value, SNI_H_LV_OBJ, &self_obj))
    {
        return sni_api_throw_error("Failed to convert argument");
    }

    if (!jerry_value_is_string(args_p[0]))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    const char *arg_text;
    arg_text = sni_tb_js2c_string(args_p[0]);
    if (!arg_text)
    {
        return sni_api_throw_error("Out of memory");
    }

    lv_label_set_text(self_obj, arg_text);
    eos_free((void *)arg_text);
    return jerry_undefined();
}

