/**
 * @brief Create a canvas object pointer to the created canvas
 *
 * @param parent (object) pointer to a parent widget May be NULL .. When NULL, the widget is created as a screen on the default display.
 *
 * @return (object) pointer to the created canvas
 */
jerry_value_t sni_api_ctor_canvas(const jerry_call_info_t *call_info_p,
                                  const jerry_value_t args_p[],
                                  const jerry_length_t args_count)
{
    if (jerry_value_is_undefined(call_info_p->new_target))
    {
        return sni_api_throw_error("Constructor must be called with new");
    }

    if (args_count != 1)
    {
        return sni_api_throw_error("Invalid argument count");
    }

    lv_obj_t *arg_parent;
    if (!sni_tb_js2c_parent(args_p[0], (void **)&arg_parent))
    {
        return sni_api_throw_error("Parent argument is required");
    }

    lv_obj_t *native_obj = lv_canvas_create(arg_parent);
    if (!sni_tb_c2js_set_object(&native_obj, SNI_H_LV_OBJ, call_info_p->this_value))
    {
        return sni_api_throw_error("Failed to bind native object");
    }
    return jerry_undefined();
}

/**
 * @brief Set a buffer for the canvas.
 *
 * @details
 * Use :ref:`lv_canvas_set_draw_buf()` instead if you need to set a buffer with alignment requirement.
 *
 * @param buf (number) buffer where content of canvas will be. The required size is (lv_image_color_format_get_px_size(cf) * w) / 8 * h) It can be allocated with :ref:`lv_malloc()` or it can be statically allocated array (e.g. static :ref:`lv_color_t` buf[100*50]) or it can be an address in RAM or external SRAM
 *
 * @param w (number) width of canvas
 *
 * @param h (number) height of canvas
 *
 * @param cf (number) color format. LV_COLOR_FORMAT...
 */
jerry_value_t sni_api_lv_canvas_set_buffer(const jerry_call_info_t *call_info_p,
                                           const jerry_value_t args_p[],
                                           const jerry_length_t args_count)
{
    if (args_count != 4)
    {
        return sni_api_throw_error("Invalid argument count");
    }

    if (!jerry_value_is_object(call_info_p->this_value))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    lv_obj_t *self_obj;
    if (!sni_tb_js2c(call_info_p->this_value, SNI_H_LV_OBJ, &self_obj))
    {
        return sni_api_throw_error("Failed to convert argument");
    }

    if (!jerry_value_is_number(args_p[0]))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    void *arg_buf;
    if (!sni_tb_js2c(args_p[0], SNI_T_PTR, &arg_buf))
    {
        return sni_api_throw_error("Failed to convert argument");
    }

    if (!jerry_value_is_number(args_p[1]))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    int32_t arg_w;
    arg_w = sni_tb_js2c_int32(args_p[1]);

    if (!jerry_value_is_number(args_p[2]))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    int32_t arg_h;
    arg_h = sni_tb_js2c_int32(args_p[2]);

    if (!jerry_value_is_number(args_p[3]))
    {
        return sni_api_throw_error("Invalid argument type");
    }
    lv_color_format_t arg_cf;
    arg_cf = sni_tb_js2c_int32(args_p[3]);

    lv_canvas_set_buffer(self_obj, arg_buf, arg_w, arg_h, arg_cf);
    return jerry_undefined();
}

